import React, { useState, useEffect } from "react";
import { getAllExamCounts } from "../services/api"; // Function to fetch counts for all franchises

const ExamCounts = () => {
    const [counts, setCounts] = useState([]);
    const [error, setError] = useState("");

    useEffect(() => {
        const fetchExamCounts = async () => {
            try {
                const countsData = await getAllExamCounts();
                setCounts(countsData);
            } catch (err) {
                console.error("Error fetching exam counts:", err);
                setError("Failed to load exam counts for all franchises. Please try again later.");
            }
        };

        fetchExamCounts();
    }, []);

    if (error) {
        return <p style={{ color: "red" }}>Error: {error}</p>;
    }

    return (
        <div>
            <h2>Exam Counts for All Franchises</h2>
            {counts.length > 0 ? (
                counts.map((franchise) => (
                    <div key={franchise.franchiseId}>
                        <h3>{franchise.franchiseName}</h3>
                        <p>Today's Exams: {franchise.counts.today}</p>
                        <p>This Week's Exams: {franchise.counts.week}</p>
                        <p>This Month's Exams: {franchise.counts.month}</p>
                    </div>
                ))
            ) : (
                <p>No data available</p>
            )}
        </div>
    );
};

export default ExamCounts;
